using System.Security.Claims;using HastaneRandevuSistemi.Data;using Microsoft.AspNetCore.Authentication;using Microsoft.AspNetCore.Authentication.Cookies;using Microsoft.AspNetCore.Mvc;
namespace HastaneRandevuSistemi.Controllers;public class AccountController:Controller{private readonly HospitalContext db;public AccountController(HospitalContext d)=>db=d;public IActionResult Login()=>User.Identity?.IsAuthenticated==true?Go(User.FindFirstValue(ClaimTypes.Role)!):View();[HttpPost][ValidateAntiForgeryToken]public async Task<IActionResult> Login(string email,string password){var u=db.Users.FirstOrDefault(x=>x.Email==email&&x.PasswordHash==DbInitializer.Hash(password));if(u==null){ViewBag.Error="E-posta veya şifre hatalı.";return View();}var c=new[]{new Claim(ClaimTypes.NameIdentifier,u.Id.ToString()),new Claim(ClaimTypes.Name,u.FullName),new Claim(ClaimTypes.Email,u.Email),new Claim(ClaimTypes.Role,u.Role)};await HttpContext.SignInAsync(CookieAuthenticationDefaults.AuthenticationScheme,new ClaimsPrincipal(new ClaimsIdentity(c,CookieAuthenticationDefaults.AuthenticationScheme)));return Go(u.Role);}public async Task<IActionResult> Logout(){await HttpContext.SignOutAsync();return RedirectToAction(nameof(Login));}public IActionResult AccessDenied()=>View();IActionResult Go(string r)=>r switch{"Hasta"=>RedirectToAction("Index","Patient"),"Doktor"=>RedirectToAction("Index","Doctor"),"Müdür"=>RedirectToAction("Index","Manager"),_=>RedirectToAction(nameof(Login))};}
